import ast
import builtins
import inspect
import os
import re
from types import ModuleType
from typing import Any, Dict, List, Optional, Set, Tuple

# ------------------------------------------------------------
# Export: globals_bundle_export
# Kind:   function
# Name:   _ⵢglobals_export__globals_bundle_export
# ------------------------------------------------------------

def globals_bundle_export(
    g: Dict[str, Any],
    support_path: str = "__bundle_support__.py",
    support_module_name: str = "__bundle_support__",
    recurse: bool = False,
    include_imports: bool = True,
    include_globals: bool = True,
    skip_private: bool = True,
    max_recurse_steps: int = 500,
) -> Dict[str, Any]:
    """
    Export non-native callables (and optionally globals) into a support file,
    returning a shim that reattaches them to your namespace.

    Returns dict with:
      - support_path
      - exported_callables: {orig_name: support_internal_name}
      - exported_globals: {orig_name: support_internal_name or '' if skipped}
      - shim: python snippet string
      - notes: list[str]
    """
    notes: List[str] = []
    exported_callables: Dict[str, str] = {}
    exported_globals: Dict[str, str] = {}

    this_file = g.get("__file__", "") or ""
    try:
        this_file_abs = os.path.abspath(this_file) if this_file else ""
    except Exception:
        this_file_abs = this_file

    INTERNAL_PREFIX = "_ⵢ"  # you asked for obscure-ish, safe identifier

    def is_module(v: Any) -> bool:
        return isinstance(v, ModuleType)

    def is_exportable_callable(v: Any) -> bool:
        return inspect.isfunction(v) or inspect.isclass(v)

    def safe_ident(s: str) -> str:
        s = re.sub(r"[^0-9a-zA-Z_ⵢ]+", "_", s)
        if not s:
            s = "x"
        if s[0].isdigit():
            s = "_" + s
        return s

    def origin_info(v: Any) -> Tuple[str, str]:
        # (module_name, file_path)
        mod = None
        try:
            mod = inspect.getmodule(v)
        except Exception:
            mod = None
        mod_name = getattr(mod, "__name__", None) or getattr(v, "__module__", None) or "unknown"
        fpath = ""
        try:
            fpath = inspect.getsourcefile(v) or inspect.getfile(v) or ""
        except Exception:
            fpath = ""
        return str(mod_name), str(fpath or "")

    def is_builtinish_name(name: str) -> bool:
        return hasattr(builtins, name)

    def is_namespace_native(v: Any) -> bool:
        # native if:
        # - module object
        # - builtin-ish
        # - source file == this file
        if is_module(v):
            return True
        n = getattr(v, "__name__", "")
        if n and is_builtinish_name(n):
            return True

        _, fpath = origin_info(v)
        if fpath and this_file_abs:
            try:
                return os.path.abspath(fpath) == this_file_abs
            except Exception:
                return fpath == this_file_abs
        return False

    def should_consider_name(name: str) -> bool:
        if name in ("__builtins__",):
            return False
        if name == "_":  # keep your framework namespace object out of export
            return False
        if skip_private and name.startswith("_"):
            return False
        return True

    def safe_literal_repr(v: Any) -> Optional[str]:
        # Only export globals that are truly sane to reconstruct with `= <repr>`
        ok_types = (type(None), bool, int, float, str, bytes, tuple, list, dict, set)
        if isinstance(v, ok_types):
            try:
                r = repr(v)
                if len(r) > 50000:
                    return None
                return r
            except Exception:
                return None
        return None

    def getsource(v: Any) -> Tuple[str, str]:
        try:
            return inspect.getsource(v).rstrip() + "\n", ""
        except Exception as e:
            return "", f"{type(e).__name__}: {e}"

    def referenced_names(v: Any) -> Set[str]:
        # best-effort dependency discovery
        names: Set[str] = set()
        try:
            if inspect.isfunction(v):
                names |= set(v.__code__.co_names)
            elif inspect.isclass(v):
                for _, member in inspect.getmembers(v):
                    if inspect.isfunction(member):
                        try:
                            names |= set(member.__code__.co_names)
                        except Exception:
                            pass
        except Exception:
            pass
        names.discard("self")
        names.discard("cls")
        return names

    def extract_top_level_imports_from_file(file_path: str) -> str:
        if not file_path:
            return ""
        try:
            with open(file_path, "r", encoding="utf-8") as f:
                src = f.read()
        except Exception:
            return ""
        try:
            tree = ast.parse(src)
        except Exception:
            # fallback naive
            out = []
            for line in src.splitlines():
                if line.startswith("import ") or line.startswith("from "):
                    out.append(line)
            return "\n".join(out).rstrip() + ("\n" if out else "")

        lines = src.splitlines(True)
        out: List[str] = []
        for node in tree.body:
            if isinstance(node, (ast.Import, ast.ImportFrom)) and hasattr(node, "lineno") and hasattr(node, "end_lineno"):
                chunk = "".join(lines[node.lineno - 1 : node.end_lineno]).rstrip("\n")
                out.append(chunk)
        return "\n".join(out).rstrip() + ("\n" if out else "")

    # ------------------------------------------------------------
    # 1) Identify initial candidates (non-native callables)
    # ------------------------------------------------------------
    initial_callables: List[str] = []
    for name, val in g.items():
        if not should_consider_name(name):
            continue
        if is_module(val):
            continue
        if is_exportable_callable(val) and not is_namespace_native(val):
            initial_callables.append(name)

    # ------------------------------------------------------------
    # 2) Optional recursion (follow referenced globals)
    # ------------------------------------------------------------
    callables_set: Set[str] = set(initial_callables)
    globals_set: Set[str] = set()

    if recurse:
        queue = list(initial_callables)
        steps = 0
        while queue and steps < max_recurse_steps:
            steps += 1
            nm = queue.pop(0)
            v = g.get(nm)
            if not is_exportable_callable(v):
                continue
            for ref in referenced_names(v):
                if ref in g and should_consider_name(ref):
                    rv = g.get(ref)
                    if is_exportable_callable(rv) and not is_namespace_native(rv) and ref not in callables_set:
                        callables_set.add(ref)
                        queue.append(ref)
                    elif include_globals:
                        # track referenced globals too
                        if not is_module(rv) and not is_exportable_callable(rv):
                            globals_set.add(ref)

    # If not recursing but include_globals=True, export non-native globals too
    if include_globals and not recurse:
        for name, val in g.items():
            if not should_consider_name(name):
                continue
            if is_module(val) or is_exportable_callable(val):
                continue
            # if it’s not trivially native, export by value when possible
            # (we treat "native" for data as: defined in this file is unknowable; so we export safe literals only)
            globals_set.add(name)

    # ------------------------------------------------------------
    # 3) Build support module grouped by origin file/module
    # ------------------------------------------------------------
    # Group callables by origin (module_name, file_path)
    grouped: Dict[Tuple[str, str], List[str]] = {}
    for name in sorted(callables_set):
        v = g.get(name)
        if not is_exportable_callable(v):
            continue
        mod_name, fpath = origin_info(v)
        grouped.setdefault((mod_name, fpath), []).append(name)

    # We'll optionally add import blocks per origin file
    import_blocks: Dict[str, str] = {}
    if include_imports:
        for (_, fpath) in grouped.keys():
            if fpath and fpath not in import_blocks:
                import_blocks[fpath] = extract_top_level_imports_from_file(fpath)

    support_lines: List[str] = []
    support_lines.append("#!/usr/bin/python3\n")
    support_lines.append("# ============================================================\n")
    support_lines.append(f"# Support module generated by globals_bundle_export\n")
    support_lines.append(f"# This file: {os.path.abspath(support_path)}\n")
    support_lines.append("# ============================================================\n\n")

    # Put a small registry mapping for debugging
    support_lines.append("EXPORT_REGISTRY = {}\n\n")

    # Write callable groups with large spacing between origin parents
    for (mod_name, fpath), names in grouped.items():
        support_lines.append("\n\n\n\n")
        support_lines.append("# ============================================================\n")
        support_lines.append(f"# ORIGIN MODULE: {mod_name}\n")
        support_lines.append(f"# ORIGIN FILE:   {fpath or '(unknown)'}\n")
        support_lines.append("# ============================================================\n\n")

        if include_imports and fpath and import_blocks.get(fpath):
            support_lines.append("# ---- extracted imports (top-level) ----\n")
            support_lines.append(import_blocks[fpath])
            if not import_blocks[fpath].endswith("\n"):
                support_lines.append("\n")
            support_lines.append("\n")

        for orig_name in names:
            v = g.get(orig_name)
            src, err = getsource(v)
            if not src:
                notes.append(f"Could not source callable {orig_name}: {err}")
                continue

            internal_name = INTERNAL_PREFIX + safe_ident(f"{mod_name}__{orig_name}")
            exported_callables[orig_name] = internal_name

            support_lines.append("# ------------------------------------------------------------\n")
            support_lines.append(f"# Export: {orig_name}\n")
            support_lines.append(f"# Kind:   {'class' if inspect.isclass(v) else 'function'}\n")
            support_lines.append(f"# Name:   {internal_name}\n")
            support_lines.append("# ------------------------------------------------------------\n\n")

            # Emit the def/class as-is
            support_lines.append(src)
            if not src.endswith("\n"):
                support_lines.append("\n")

            # Alias it to internal_name, and optionally delete the original
            support_lines.append(f"\n{internal_name} = {orig_name}\n")
            support_lines.append(f"EXPORT_REGISTRY[{orig_name!r}] = {internal_name!r}\n")
            support_lines.append(f"try:\n    del {orig_name}\nexcept Exception:\n    pass\n\n")

    # Export globals (simple literals only)
    if include_globals and globals_set:
        support_lines.append("\n\n\n\n")
        support_lines.append("# ============================================================\n")
        support_lines.append("# GLOBAL VARIABLES (safe-literal only)\n")
        support_lines.append("# ============================================================\n\n")

        for name in sorted(globals_set):
            if name in exported_callables:
                continue
            v = g.get(name)
            if is_module(v) or is_exportable_callable(v):
                continue

            r = safe_literal_repr(v)
            if r is None:
                exported_globals[name] = ""
                support_lines.append(f"# Skipped global {name!r}: not safely representable\n")
                continue

            internal_name = INTERNAL_PREFIX + safe_ident(f"global__{name}")
            exported_globals[name] = internal_name

            support_lines.append("# ------------------------------------------------------------\n")
            support_lines.append(f"# Global: {name}\n")
            support_lines.append(f"# Name:   {internal_name}\n")
            support_lines.append("# ------------------------------------------------------------\n")
            support_lines.append(f"{internal_name} = {r}\n")
            support_lines.append(f"EXPORT_REGISTRY[{name!r}] = {internal_name!r}\n\n")

    # Write the support file
    with open(support_path, "w", encoding="utf-8") as f:
        f.write("".join(support_lines))

    # ------------------------------------------------------------
    # 4) Build shim that attaches to your namespace object (_)
    # ------------------------------------------------------------
    shim_lines: List[str] = []
    shim_lines.append(f"import {support_module_name} as __bs\n\n")
    shim_lines.append("# Rehydrate exported callables\n")
    for orig_name in sorted(exported_callables.keys()):
        shim_lines.append(f"{orig_name} = __bs.{exported_callables[orig_name]}\n")
    shim_lines.append("\n# Rehydrate exported globals (safe literals only)\n")
    for orig_name in sorted(exported_globals.keys()):
        internal = exported_globals[orig_name]
        if internal:
            shim_lines.append(f"{orig_name} = __bs.{internal}\n")

    # Also provide an alternate wiring style for your Meta_Namespace pattern:
    shim_lines.append("\n# Optional: attach into your '_' namespace object\n")
    shim_lines.append("# Example:\n")
    shim_lines.append("# _.focus = __bs._ⵢ<...>\n")
    for orig_name in sorted(exported_callables.keys()):
        shim_lines.append(f"# _.{orig_name} = __bs.{exported_callables[orig_name]}\n")

    result = {
        "support_path": os.path.abspath(support_path),
        "support_module_name": support_module_name,
        "exported_callables": exported_callables,
        "exported_globals": exported_globals,
        "shim": "".join(shim_lines),
        "notes": notes,
    }
    return result

